begin;
set local search_path=public,extensions;
select plan(50);

select has_table('public','reward_rule_versions','reward rules are versioned');
select has_table('public','reward_grants','reward grants are durable evidence');
select has_table('public','referral_links','referral links are traceable');
select has_table('public','referral_touchpoints','referral touchpoints are append-only');
select has_table('public','referral_conversions','referral conversions preserve origin');
select has_table('public','referral_conversion_events','referral conversion history exists');
select has_table('public','measurement_baselines','measurement baselines are verified snapshots');
select has_table('public','recommendation_roi_snapshots','recommendation ROI snapshots exist');
select has_table('public','savings_measurements','verified savings measurements exist');

select has_function('public','create_reward_rule_version',array['text','text','text','text','bigint','bigint','bigint','integer','integer','integer','jsonb','boolean','timestamp with time zone','timestamp with time zone','text','text','uuid'],'reward rule command exists');
select has_function('public','award_reward',array['uuid','uuid','uuid','text','text','text','jsonb','text','text','uuid'],'reward award command exists');
select has_function('public','create_referral_link',array['uuid','text','text','text','timestamp with time zone','integer','text','uuid'],'referral link command exists');
select has_function('public','record_referral_touchpoint',array['text','text','text','text','uuid'],'referral touchpoint command exists');
select has_function('public','register_referral_conversion',array['text','uuid','jsonb','jsonb','text','text','uuid'],'referral registration command exists');
select has_function('public','advance_referral_conversion',array['uuid','text','jsonb','text','integer','text','uuid'],'referral stage command exists');
select has_function('public','capture_verified_baseline',array['uuid','text','uuid','text','bigint','text','date','date','text','text','jsonb','text','text','text','uuid'],'baseline verification command exists');
select has_function('public','calculate_recommendation_roi',array['uuid','uuid','bigint','bigint','date','date','text','text','jsonb','text','text','text','uuid'],'ROI calculation command exists');
select has_function('public','record_verified_savings',array['uuid','bigint','date','date','text','text','jsonb','text','text','text','uuid'],'savings recording command exists');

select ok((select bool_and(p.prosecdef and p.proconfig::text like '%search_path=pg_catalog%')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname in('create_reward_rule_version','award_reward','create_referral_link','record_referral_touchpoint','register_referral_conversion','advance_referral_conversion','capture_verified_baseline','calculate_recommendation_roi','record_verified_savings')),'all commands are security definer with fixed search paths');
select ok(not has_function_privilege('anon','public.award_reward(uuid,uuid,uuid,text,text,text,jsonb,text,text,uuid)','EXECUTE')and not has_function_privilege('service_role','public.calculate_recommendation_roi(uuid,uuid,bigint,bigint,date,date,text,text,jsonb,text,text,text,uuid)','EXECUTE'),'anonymous and service roles cannot award rewards or calculate ROI');
select ok(has_function_privilege('authenticated','public.record_verified_savings(uuid,bigint,date,date,text,text,jsonb,text,text,text,uuid)','EXECUTE'),'authenticated actors can invoke governed savings command');
select ok(not has_table_privilege('authenticated','public.reward_grants','INSERT')and not has_table_privilege('authenticated','public.measurement_baselines','UPDATE')and not has_table_privilege('authenticated','public.savings_measurements','DELETE'),'direct mutations are denied');
select ok((select bool_and(c.relrowsecurity)from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relname in('reward_rule_versions','reward_grants','referral_links','referral_touchpoints','referral_conversions','referral_conversion_events','measurement_baselines','recommendation_roi_snapshots','savings_measurements')),'every module table enforces RLS');
select ok((select count(*)=0 from information_schema.columns where table_schema='public'and table_name in('reward_rule_versions','reward_grants','measurement_baselines','recommendation_roi_snapshots','savings_measurements')and data_type in('real','double precision')),'rewards ROI and savings contain no floating point fields');
select col_type_is('public','measurement_baselines','baseline_amount_minor','bigint','baseline money uses integer minor units');
select col_type_is('public','recommendation_roi_snapshots','implementation_cost_minor','bigint','ROI cost uses integer minor units');
select col_type_is('public','savings_measurements','savings_amount_minor','bigint','savings use integer minor units');
select ok((select count(*)=7 from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relname in('reward_rule_versions','reward_grants','referral_touchpoints','referral_conversion_events','measurement_baselines','recommendation_roi_snapshots','savings_measurements')and not t.tgisinternal and t.tgname like '%immutable'),'critical financial and evidence snapshots are immutable');
select ok((select p.prosrc like '%public.issue_credits%'and p.prosrc like '%''BONUS''%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='award_reward'),'reward grants use the authorised immutable credit ledger RPC');
select ok((select p.prosrc not like '%insert into public.credit_ledger_entries%'and p.prosrc not like '%update public.credit_wallets%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='award_reward'),'reward command never mutates balances or ledger tables directly');
select ok((select p.prosrc like '%REWARD_RECIPIENT_CAP_EXCEEDED%'and p.prosrc like '%REWARD_GLOBAL_CAP_EXCEEDED%'and p.prosrc like '%REWARD_COOLDOWN_ACTIVE%'and p.prosrc like '%pg_advisory_xact_lock%'and p.prosrc like '%e.eligibility_snapshot@>v.eligibility_rule%'and p.prosrc like '%APPROVED_REWARD_SOURCE_REQUIRED%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='award_reward'),'server-event eligibility, approved source, caps and cooldown are concurrency guarded');
select ok((select count(*)=2 from pg_constraint where conrelid='public.reward_grants'::regclass and contype='u'and pg_get_constraintdef(oid)like '%rule_code%'and(pg_get_constraintdef(oid)like '%anti_abuse_key_hash%'or pg_get_constraintdef(oid)like '%trigger_reference_type%')),'anti-abuse and trigger uniqueness span reward versions');
select ok((select p.prosrc like '%IDEMPOTENCY_PAYLOAD_MISMATCH%'and p.prosrc like '%IDEMPOTENCY_IN_PROGRESS%'and p.prosrc like '%pg_advisory_xact_lock%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname='begin_rewards_command'),'all commands use canonical concurrency-safe idempotency');
select ok((select bool_and(p.prosrc like '%audit_events%')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname in('create_reward_rule_version','award_reward','create_referral_link','record_referral_touchpoint','register_referral_conversion','advance_referral_conversion','capture_verified_baseline','calculate_recommendation_roi','record_verified_savings')),'every sensitive command writes audit evidence');
select ok((select bool_and(p.prosrc like '%event_outbox%')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname in('create_reward_rule_version','award_reward','create_referral_link','record_referral_touchpoint','register_referral_conversion','advance_referral_conversion','capture_verified_baseline','calculate_recommendation_roi','record_verified_savings')),'every sensitive command writes an outbox event');
select ok((select p.prosrc like '%REGISTERED%PROFILE_STARTED%'and p.prosrc like '%PROFILE_STARTED%VERIFIED%'and p.prosrc like '%VERIFIED%ACTIVE%'and p.prosrc like '%STALE_REFERRAL_CONVERSION%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='advance_referral_conversion'),'referral conversion stages are ordered with optimistic concurrency');
select ok(exists(select 1 from pg_constraint where conrelid='public.referral_conversions'::regclass and contype='u'and pg_get_constraintdef(oid)like '%target_organization_id%')and exists(select 1 from information_schema.columns where table_schema='public'and table_name='referral_conversions'and column_name='origin_snapshot'and is_nullable='NO'),'one immutable referral origin is retained per target organization');
select ok(exists(select 1 from pg_constraint where conrelid='public.measurement_baselines'::regclass and contype='c'and pg_get_constraintdef(oid)like '%VERIFIED%')and exists(select 1 from pg_constraint where conrelid='public.measurement_baselines'::regclass and contype='c'and pg_get_constraintdef(oid)like '%evidence_refs%'),'baselines must be verified and evidence-backed');
select ok((select p.prosrc like '%numeric*10000%'and p.prosrc like '%implementation_cost_minor::numeric%'and p.prosrc not like '%double precision%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='calculate_recommendation_roi'),'ROI uses exact numeric basis-point arithmetic');
select ok((select p.prosrc like '%VERIFIED_RECOMMENDATION_BASELINE_REQUIRED%'and p.prosrc like '%verification_status=''VERIFIED''%'and p.prosrc like '%b.subject_type<>''RECOMMENDATION''%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='calculate_recommendation_roi'),'ROI is impossible without a verified recommendation baseline');
select ok((select bool_and(p.prosrc like '%p_actual_period_end-p_actual_period_start%'and p.prosrc like '%b.period_end-b.period_start%')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname in('calculate_recommendation_roi','record_verified_savings')),'ROI and savings require comparable period durations');
select ok((select p.prosrc like '%p_actual_amount_minor>b.baseline_amount_minor%'and p.prosrc like '%baseline_amount_minor-p_actual_amount_minor%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='record_verified_savings'),'savings cannot be claimed when actual cost exceeds baseline');
select ok((select qual like '%organization_id%'and qual like '%is_active_org_member%'from pg_policies where schemaname='public'and tablename='measurement_baselines'and policyname='measurement_baselines_tenant_read'),'baseline reads are tenant scoped');
select ok((select qual like '%organization_id%'and qual like '%is_active_org_member%'from pg_policies where schemaname='public'and tablename='recommendation_roi_snapshots'and policyname='recommendation_roi_tenant_read'),'ROI reads are tenant scoped');
select ok((select qual like '%organization_id%'and qual like '%is_active_org_member%'from pg_policies where schemaname='public'and tablename='savings_measurements'and policyname='savings_measurements_tenant_read'),'savings reads are tenant scoped');
select ok((select qual like '%source_organization_id%'and qual like '%target_organization_id%'from pg_policies where schemaname='public'and tablename='referral_conversions'and policyname='referral_conversions_scoped_read'),'referral conversions are limited to their two participating tenants');
select has_index('public','reward_grants','reward_grants_recipient_window_idx','reward recipient cap window is indexed');
select has_index('public','referral_conversions','referral_conversions_target_idx','referral target lookup is indexed');
select has_index('public','measurement_baselines','measurement_baselines_subject_idx','latest verified baseline lookup is indexed');
select has_index('public','savings_measurements','savings_measurements_org_idx','savings center timeline is indexed');

select * from finish();
rollback;
